        return 0;
    }

    int maxLength = 0;

    for (String str : strings) {
        if (str.length() > maxLength) {
            boolean isLargest = true;

            for (String s : strings) {
                if (!s.contains(str) && !s.contains(new StringBuilder(str).reverse().toString())) {
                    isLargest = false;
                    break;
                }
            }

            if (isLargest) {
