    dfs(grid, row - 1, col); // North
    dfs(grid, row + 1, col); // South
    dfs(grid, row, col - 1); // West
    dfs(grid, row, col + 1); // East
    dfs(grid, row - 1, col - 1); // Northwest
    dfs(grid, row - 1, col + 1); // Northeast
    dfs(grid, row + 1, col - 1); // Southwest
    dfs(grid, row + 1, col + 1); // Southeast
}

