public static int maxRegions(int N) {
    // Base case: 0 triangles divide the plane into 1 region
    if (N == 0) {
        return 1;
    }

    // The maximum number of regions is given by the formula: R(N) = 2 * N * (N + 1) / 2 + 1
    return 2 * N * (N + 1) / 2 + 1;
}

public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Input must be a non-negative integer.");
    }

    // Base cases
    if (N == 0) {
        return 1;
    } else if (N == 1) {
        return 2;
    }

    // Each new triangle can intersect all existing regions
    return 1 + N + (N * (N - 1)) / 2;
}

