public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            graph.add(new ArrayList<>());
        }

        for (int[] path : paths) {
            int u = path[0];
            int v = path[1];
            graph.get(u).add(v);
            graph.get(v).add(u);
        }

        Set<Integer> visited = new HashSet<>();
        Stack<Integer> stack = new Stack<>();
        stack.push(start[0]);

        while (!stack.isEmpty()) {
            int current = stack.pop();
            if (!visited.contains(current)) {
                visited.add(current);

                if (current == end[0] && current == end[1]) {
                    return "can be travelled";
                }

                for (int neighbor : graph.get(current)) {
                    stack.push(neighbor);
                }
            }
        }

        return "cannot be travelled";
    }

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[][] graph = new boolean[n][n];
    for (int[] path : paths) {
        graph[path[0]][path[1]] = true;
        graph[path[1]][path[0]] = true;
    }

    boolean[] visited = new boolean[n];
    boolean canTravel = dfs(start[0], end[0], graph, visited);

    return canTravel ? "can be travelled" : "cannot be travelled";
}

private static boolean dfs(int current, int destination, boolean[][] graph, boolean[] visited) {
    if (current == destination) {
        return true;
    }

    visited[current] = true;

    for (int i = 0; i < graph.length; i++) {
        if (graph[current][i] && !visited[i]) {
            if (dfs(i, destination, graph, visited)) {
                return true;
            }
        }
    }

    visited[current] = false;
    return false;
}

