        int y1 = paths[i + 1];
        int x2 = paths[i + 2];
        int y2 = paths[i + 3];

        if ((x1 == start[0] && y1 == start[1]) || (x2 == start[0] && y2 == start[1])) {
            if ((x1 == x2 && Math.abs(y1 - y2) == 1) || (y1 == y2 && Math.abs(x1 - x2) == 1)) {
                visited[x1 * n + y1] = true;
                visited[x2 * n + y2] = true;
            }
        }
    }

    boolean current = false;
    for (boolean v : visited) {
        if (v) {
            current = true;
            break;
        }
    }

    while (current) {
        current = false;
        for (int i = 0; i < paths.length; i += 3) {
            int x1 = paths[i];
            int y1 = paths[i + 1];
            int x2 = paths[i + 2];
            int y2 = paths[i + 3];

            if (visited[x1 * n + y1] && goal[x2 * n + y2] && !visited[x2 * n + y2]) {
                visited[x2 * n + y2] = true;
                current = true;
            } else if (visited[x2 * n + y2] && goal[x1 * n + y1] && !visited[x1 * n + y1]) {
                visited[x1 * n + y1] = true;
                current = true;
            }
        }
    }

    for (boolean g : goal) {
        if (!g) {
            return "cannot be travelled";
        }
    }

    return "can be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[][] graph = new boolean[n][n];
    for (int i = 0; i < paths.length; i++) {
        graph[paths[i][0]][paths[i][1]] = true;
        graph[paths[i][1]][paths[i][0]] = true;
    }

    boolean[] visited = new boolean[n];
    return dfs(graph, start[0], end[0], visited) ? "can be travelled" : "cannot be travelled";
}

private static boolean dfs(boolean[][] graph, int current, int end, boolean[] visited) {
    if (current == end) {
        return true;
    }
    visited[current] = true;
    for (int i = 0; i < graph.length; i++) {
        if (graph[current][i] && !visited[i]) {
            if (dfs(graph, i, end, visited)) {
                return true;
            }
        }
    }
    visited[current] = false;
    return false;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
        Set<Integer> visited = new HashSet<>();
        boolean[] canReach = new boolean[n * n];
        canReach[start[0] * n + start[1]] = true;

        for (int[] path : paths) {
            int u = path[0] * n + path[1];
            int v = path[2] * n + path[3];
            canReach[v] = true;
        }

        for (int i = 0; i < n * n; i++) {
            if (canReach[i]) {
                int row = i / n;
                int col = i % n;
                int[] neighbors = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

                for (int[] neighbor : neighbors) {
                    int newRow = row + neighbor[0];
                    int newCol = col + neighbor[1];
                    int newIndex = newRow * n + newCol;

                    if (newRow >= 0 && newRow < n && newCol >= 0 && newCol < n && !visited.contains(newIndex)) {
                        visited.add(newIndex);
                        if (newIndex == end[0] * n + end[1]) {
                            return "can be travelled";
                        }
                    }
                }
            }
        }

        return "cannot be travelled";
    }

public static String appx(String word1, String word2) {
        Set<Character> set1 = new HashSet<>();
        Set<Character> set2 = new HashSet<>();

        for (char c : word1.toCharArray()) {
            set1.add(c);
        }

        for (char c : word2.toCharArray()) {
            set2.add(c);
        }

        set1.retainAll(set2);
        int commonLetters = set1.size();
        int sumOfLengths = word1.length() + word2.length();

        if (commonLetters == 0 || sumOfLengths == 0) {
            return "appx(" + word1 + ", " + word2 + ") = 0";
        }

        int gcd = gcd(commonLetters, sumOfLengths);
        return "appx(" + word1 + ", " + word2 + ") = " + (commonLetters / gcd) + "/" + (sumOfLengths / gcd);
    }

private static int gcd(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

