public static String appx(String word1, String word2) {
        int commonLetters = 0;
        int totalLength = word1.length() + word2.length();

        word1 = word1.toLowerCase();
        word2 = word2.toLowerCase();

        for (int i = 0; i < word1.length(); i++) {
            for (int j = 0; j < word2.length(); j++) {
                if (word1.charAt(i) == word2.charAt(j)) {
                    commonLetters++;
                    break;
                }
            }
        }

        BigInteger numerator = BigInteger.valueOf(commonLetters);
        BigInteger denominator = BigInteger.valueOf(totalLength);

        // Simplify the fraction
        BigInteger gcd = numerator.gcd(denominator);
        numerator = numerator.divide(gcd);
        denominator = denominator.divide(gcd);

        return "appx(" + word1.toUpperCase() + ", " + word2.toUpperCase() + ") = " + numerator + "/" + denominator;
    }

public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null) {
        throw new IllegalArgumentException("Input words cannot be null.");
    }

    word1 = word1.toLowerCase();
    word2 = word2.toLowerCase();

    int commonCount = 0;
    boolean[] checkedChars = new boolean[word2.length()];

    for (int i = 0; i < word1.length(); i++) {
        char currentChar = word1.charAt(i);
        for (int j = 0; j < word2.length(); j++) {
            if (!checkedChars[j] && word2.charAt(j) == currentChar) {
                commonCount++;
                checkedChars[j] = true;
                break;
            }
        }
    }

    int sumOfLengths = word1.length() + word2.length();

    if (commonCount == 0 || sumOfLengths == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }

    int gcd = calculateGCD(commonCount, sumOfLengths);

    return "appx(" + word1 + ", " + word2 + ") = " + (commonCount / gcd) + "/" + (sumOfLengths / gcd);
}

private static int calculateGCD(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

