public boolean canArrange(int[] arr, int k) {
    int[] remainderCounts = new int[k];
    for (int num : arr) {
        remainderCounts[(num % k + k) % k]++;
    }
    if (remainderCounts[0] % 2 != 0) {
        return false;
    }
    for (int i = 1; i <= k / 2; i++) {
        if (remainderCounts[i] != remainderCounts[k - i]) {
            return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
        int n = arr.length;
        if (n % 2 != 0) {
            return false;
        }

        Map<Integer, Integer> remainderCount = new HashMap<>();
        for (int num : arr) {
            int remainder = ((num % k) + k) % k;
            remainderCount.put(remainder, remainderCount.getOrDefault(remainder, 0) + 1);
        }

        for (int remainder : remainderCount.keySet()) {
            if (remainder == 0) {
                if (remainderCount.get(remainder) % 2 != 0) {
                    return false;
                }
            } else if (!remainderCount.containsKey(k - remainder)) {
                return false;
            } else if (!remainderCount.get(remainder).equals(remainderCount.get(k - remainder))) {
                return false;
            }
        }

        return true;
    }

