public boolean canArrange(int[] arr, int k) {
    // Create an array to store the remainders
    int[] remainderCount = new int[k];

    // Count the remainders when each element in the array is divided by k
    for (int num : arr) {
        int remainder = ((num % k) + k) % k; // Ensure non-negative remainders
        remainderCount[remainder]++;
    }

    // Check the conditions for the pairs
    if (remainderCount[0] % 2 != 0) {
        return false; // The count of elements with remainder 0 must be even
    }

    for (int i = 1; i <= k / 2; i++) {
        if (remainderCount[i] != remainderCount[k - i]) {
            return false; // The counts of elements with remainder i and k-i must be equal
        }
    }

    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<Integer>[] graph = new ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new ArrayList<>();
    }
    for (int[] edge : edges) {
        graph[edge[0]].add(edge[1]);
        graph[edge[1]].add(edge[0]);
    }
    return dfs(0, -1, graph, hasApple) * 2;
}

private int dfs(int node, int parent, List<Integer>[] graph, boolean[] hasApple) {
    int time = 0;
    for (int neighbor : graph[node]) {
        if (neighbor == parent) continue;
        time += dfs(neighbor, node, graph, hasApple);
    }
    if ((time > 0 || hasApple[node]) && node != 0) {
        return time + 1;
    }
    return time;
}

