public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) {
        return false;
    }
    double sum = 0;
    for (int num : nums) {
        sum += num;
    }
    for (int i = 1; i < n; i++) {
        if ((i * sum) % n == 0) {
            return true;
        }
    }
    boolean[][] dp = new boolean[n + 1][n + 1];
    dp[0][0] = true;
    for (int i = 1; i <= n; i++) {
        dp[i][0] = true;
        int num = nums[i - 1];
        for (int j = 1; j <= n; j++) {
            if (j >= num) {
                dp[i][j] = dp[i - 1][j] || dp[i - 1][j - num];
            }
        }
    }
    for (int i = 1; i < n; i++) {
        for (int j = i; j <= n; j++) {
            if (dp[i][j] && (j * sum) % n == 0) {
                return true;
            }
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] A) {
        int n = A.length, s = 0;
        for (int a : A) s += a;
        for (int i = 1; i <= n / 2; i++) {
            Set<Integer> set = new HashSet<>();
            dfs(A, i, 0, 0, s, set);
            if (set.contains(i * s)) return true;
        }
        return false;
    }

private void dfs(int[] A, int count, int index, int sum, int total, Set<Integer> set) {
        if (count == 0) {
            set.add(sum);
            return;
        }
        if (index >= A.length) return;
        dfs(A, count, index + 1, sum, total, set);
        dfs(A, count - 1, index + 1, sum + A[index], total, set);
    }

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    for (int i = 1; i <= n / 2; i++) {
        if (canAchieveSum(nums, 0, sum * i, i)) {
            return true;
        }
    }
    return false;
}

private boolean canAchieveSum(int[] nums, int start, int target, int length) {
    if (length == 0) {
        return target == 0;
    }
    if (start >= nums.length) {
        return false;
    }
    return canAchieveSum(nums, start + 1, target - nums[start], length - 1) ||
           canAchieveSum(nums, start + 1, target, length);
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n == 1) {
        return false;
    }

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    for (int i = 1; i <= n / 2; i++) {
        if (sum * i % n == 0) {
            return true;
        }
    }

    Set<Integer>[] dp = new Set[n + 1];
    for (int i = 0; i <= n; i++) {
        dp[i] = new HashSet<>();
    }

    dp[0].add(0);

    for (int num : nums) {
        for (int i = n - 1; i >= 1; i--) {
            for (int prevSum : dp[i - 1]) {
                dp[i].add(prevSum + num);
            }
        }
    }

    for (int i = 1; i < n; i++) {
        if (sum * i % n == 0) {
            int target = sum * i / n;
            if (dp[i].contains(target)) {
                return true;
            }
        }
    }

    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    int n = nums.length;
    int[] dp = new int[sum + 1];
    dp[0] = 1;

    for (int num : nums) {
        for (int i = sum - num; i >= 0; i--) {
            dp[i + num] += dp[i];
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        for (int j = 0; j <= sum; j++) {
            if (dp[j] > 0 && (sum * i) % n == 0 && (j * i) % n == 0) {
                return true;
            }
        }
    }

    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < n; i++) {
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i];
    }
    return Math.min(dp[n - 1], dp[n - 2]);
}

public int minCostClimbingStairs(int[] cost) {
