public boolean hasAllCodes(String s, int k) {
    // Check if s has enough characters to contain all possible k-length substrings
    if (s.length() < Math.pow(2, k)) {
        return false;
    }

    // Use a set to store unique k-length substrings
    Set<String> codeSet = new HashSet<>();

    // Iterate through the string and add k-length substrings to the set
    for (int i = 0; i <= s.length() - k; i++) {
        codeSet.add(s.substring(i, i + k));
    }

    // Check if the set contains all possible k-length substrings
    return codeSet.size() == Math.pow(2, k);
}

public boolean hasAllCodes(String s, int k) {
    Set<String> seen = new HashSet<>();
    int n = s.length();

    for (int i = 0; i <= n - k; i++) {
        String substring = s.substring(i, i + k);
        seen.add(substring);
    }

    return seen.size() == (1 << k);
}

