public boolean hasAllCodes(String s, int k) {
    if (s.length() < (1 << k)) {
        return false;
    }

    int target = 1 << k;
    Set<Integer> set = new HashSet<>();
    int current = 0;

    for (int i = 0; i < s.length(); i++) {
        current = (current << 1) | (s.charAt(i) - '0');
        if (i >= k) {
            current &= target - 1;
        }
        if (i >= k - 1) {
            set.add(current);
        }
    }

    return set.size() == target;
}

