public int minInsertions(String s) {
    int count = 0;
    int imbalance = 0;

    for (char c : s.toCharArray()) {
        if (c == '(') {
            if (imbalance % 2 == 1) {
                count++;
                imbalance--;
            }
            imbalance++;
        } else {
            imbalance--;
            if (imbalance == -1) {
                count++;
                imbalance = 1;
            }
        }
    }

    return count + imbalance;
}

public int minInsertions(String s) {
    int balance = 0;
    int insertions = 0;
    int i = 0;

    while (i < s.length()) {
        if (s.charAt(i) == '(') {
            balance++;
        } else {
            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                i++;
            } else {
                insertions++;
            }
            balance--;
        }

        if (balance < 0) {
            insertions++;
            balance = 0;
        }

        i++;
    }

    return insertions + balance * 2;
}

public int minInsertions(String s) {
    int open = 0, close = 0, ans = 0;
    for (char c : s.toCharArray()) {
        if (c == '(') {
            if (close % 2 == 1) {
                ans++;
                close--;
            }
            open++;
        } else {
            close++;
            if (close == 2) {
                close = 0;
                open--;
            }
        }
    }
    return ans + open * 2 + (close % 2 == 1 ? 2 : 0);
}

