public int minInsertions(String s) {
    int open = 0;
    int close = 0;
    int insertions = 0;

    for (char c : s.toCharArray()) {
        if (c == '(') {
            if (close % 2 == 1) {
                insertions++;
                close -= 1;
            }
            open++;
        } else {
            close++;
            if (close > 2 * open) {
                insertions += close - 2 * open;
                open = close / 2;
            }
        }
