public int maxUniqueSplit(String s) {
        Set<String> uniqueSubstrings = new HashSet<>();
        return backtrack(s, uniqueSubstrings);
    }

private int backtrack(String s, Set<String> uniqueSubstrings) {
        if (s.isEmpty()) {
            return uniqueSubstrings.size();
        }

        int maxUnique = 0;
        for (int i = 1; i <= s.length(); i++) {
            String substring = s.substring(0, i);
            if (uniqueSubstrings.add(substring)) {
                maxUnique = Math.max(maxUnique, backtrack(s.substring(i), uniqueSubstrings));
                uniqueSubstrings.remove(substring);
            }
        }

        return maxUnique;
    }

