public static List<Integer> findSteppingNumbers(int low, int high) {
        List<Integer> result = new ArrayList<>();
        if (low > high) {
            return result;
        }

        Queue<Integer> que = new LinkedList<>();
        for (int i = 1; i <= 9; i++) {
            que.offer(i);
        }

        while (!que.isEmpty()) {
            int num = que.poll();
            if (num <= high && num >= low) {
                result.add(num);
            }
            if (num == 0 || num > high) {
                continue;
            }
            int lastDigit = num % 10;
            if (lastDigit > 0) {
                que.offer(num * 10 + lastDigit - 1);
            }
            if (lastDigit < 9) {
                que.offer(num * 10 + lastDigit + 1);
            }
        }

        return result;
    }

