public static int countDigitOne(int n) {
    if (n < 0) {
        return 0;
    }
    long count = 0;
    long factor = 1;
    long lowerNumbers = n;
    long currentDigit = 0;
    long higherNumbers = 0;

    while (lowerNumbers > 0 || currentDigit > 0) {
        lowerNumbers = n - (n / factor) * factor;
        currentDigit = (n / factor) % 10;
        higherNumbers = n / (factor * 10);

        if (currentDigit == 0) {
            count += higherNumbers * factor;
        } else if (currentDigit == 1) {
            count += higherNumbers * factor + lowerNumbers + 1;
        } else {
            count += (higherNumbers + 1) * factor;
        }

        factor *= 10;
    }

    return (int) count;
}

