                        int newCol = j + direction[0][1] * k;

                        if (newRow >= 0 && newRow < m && newCol >= 0 && newCol < n && mat[newRow][newCol] == 1) {
                            len++;
                        } else {
                            break;
                        }
                    }

                    maxLen = Math.max(maxLen, len);
                }
            }
        }
    }

    return maxLen;
}

