public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int maxLength = 0;

    // Arrays to store the count of continuous 1s in rows, columns, diagonals, and anti-diagonals
    int[] rowCounts = new int[rows];
    int[] colCounts = new int[cols];
    int[] diagCounts = new int[rows + cols];
    int[] antiDiagCounts = new int[rows + cols];

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (mat[i][j] == 1) {
                // Update row counts
                rowCounts[i] = rowCounts[i] + 1;
                // Update column counts
                colCounts[j] = colCounts[j] + 1;
                // Update diagonal counts (top-left to bottom-right)
                diagCounts[i - j + cols] = diagCounts[i - j + cols] + 1;
                // Update anti-diagonal counts (top-right to bottom-left)
                antiDiagCounts[i + j] = antiDiagCounts[i + j] + 1;

                // Update the maximum length found
                maxLength = Math.max(maxLength, rowCounts[i]);
                maxLength = Math.max(maxLength, colCounts[j]);
                maxLength = Math.max(maxLength, diagCounts[i - j + cols]);
                maxLength = Math.max(maxLength, antiDiagCounts[i + j]);
            } else {
                // Reset counts when encountering 0
                rowCounts[i] = 0;
                colCounts[j] = 0;
                diagCounts[i - j + cols] = 0;
                antiDiagCounts[i + j] = 0;
            }
        }
    }
    return maxLength;
}

public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }

    StringBuilder result = new StringBuilder();
    String num = String.valueOf(n);
    int length = num.length();

    for (int i = 0; i < length; i++) {
        if (i > 0 && (length - i) % 3 == 0) {
            result.append('.');
        }
        result.append(num.charAt(i));
    }

    return result.toString();
}

public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }

    boolean isNegative = n < 0;
    n = Math.abs(n);

    StringBuilder result = new StringBuilder();
    int count = 0;

    while (n > 0) {
        if (count > 0 && count % 3 == 0) {
            result.insert(0, ".");
        }
        result.insert(0, n % 10);
        n /= 10;
        count++;
    }

    if (isNegative) {
        result.insert(0, "-");
    }

    return result.toString();
}

