public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }

    String numStr = Integer.toString(n);
    StringBuilder sb = new StringBuilder();
    int len = numStr.length();
    int count = 0;

    for (int i = len - 1; i >= 0; i--) {
        count++;
        sb.append(numStr.charAt(i));
        if (count % 3 == 0 && i != 0) {
            sb.append(".");
        }
    }

    return sb.reverse().toString();
}

public static String addThousandSeparator(int n) {
    if (n == 0) {
        return "0";
    }

    boolean isNegative = n < 0;
    StringBuilder sb = new StringBuilder();
    String numberStr = Integer.toString(Math.abs(n));

    while (sb.length() < numberStr.length()) {
        int remainingLength = numberStr.length() - sb.length();
        int digitsToAdd = Math.min(3, remainingLength);
        sb.insert(0, numberStr.substring(numberStr.length() - digitsToAdd));
        if (sb.length() < numberStr.length()) {
            sb.insert(0, ".");
        }
    }

    return isNegative ? "-" + sb.toString() : sb.toString();
}

public static int squarePermutations(int[] A) {
    return helper(A, 0, 1);
}

private static int helper(int[] A, int start, int target) {
    if (start == A.length - 1) {
        int sum = A[start] + A[0];
        return isPerfectSquare(sum) ? 1 : 0;
    }

    int count = 0;
    for (int i = start + 1; i < A.length; i++) {
        int sum = A[start] + A[i];
        if (isPerfectSquare(sum)) {
            int temp = A[start + 1];
            A[start + 1] = A[i];
            A[i] = temp;
            count += helper(A, start + 2, A[start]);
            temp = A[start + 1];
            A[start + 1] = A[i];
            A[i] = temp;
        }
    }

    return count;
}

private static boolean isPerfectSquare(int num) {
    int root = (int) Math.sqrt(num);
    return root * root == num;
}

public static int squarePermutations(int[] A) {
    int[] count = new int[A.length];
    count[0] = 1;
    int result = 0;

    for (int i = 1; i < A.length; i++) {
        for (int j = 0; j < i; j++) {
            int sum = A[i] + A[j];
            int sqrt = (int) Math.sqrt(sum);
            if (sqrt * sqrt == sum) {
                count[i] += count[j];
            }
        }
        if (A[i] == A[i - 1]) {
            count[i] += count[i - 1];
        }
    }

    for (int i = 0; i < A.length - 1; i++) {
        int sum = A[i] + A[i + 1];
        int sqrt = (int) Math.sqrt(sum);
        if (sqrt * sqrt == sum) {
            result += count[i];
        }
    }

    return result;
}

public static int squarePermutations(int[] A) {
    int count = 0;
    // Check all permutations for square array
    permute(A, 0, A.length, count);
    return count;
}

private static void permute(int[] A, int start, int end, int count) {
    if (start == end) {
        if (isSquareArray(A)) {
            count++;
        }
    } else {
        for (int i = start; i < end; i++) {
            swap(A, start, i);
            permute(A, start + 1, end, count);
            swap(A, start, i); // backtrack
        }
    }
}

private static boolean isSquareArray(int[] A) {
    for (int i = 0; i < A.length - 1; i++) {
        int sum = A[i] + A[i + 1];
        int root = (int) Math.sqrt(sum);
        if (root * root != sum) {
            return false;
        }
    }
    return true;
}

private static void swap(int[] A, int i, int j) {
    int temp = A[i];
    A[i] = A[j];
    A[j] = temp;
}

