private static int countPermutations(int[] A, boolean[] used, int index) {
        if (index == A.length) {
            return 1;
        }

        int count = 0;
        for (int i = 0; i < A.length; i++) {
            if (!used[i] && isPerfectSquare(A[index - 1] + A[i])) {
                used[i] = true;
                count += countPermutations(A, used, index + 1);
                used[i] = false;
            }
        }

        return count;
    }

private static boolean isPerfectSquare(int n) {
        if (n < 0) {
            return false;
        }
        int root = (int) Math.sqrt(n);
        return root * root == n;
    }

public static int squarePermutations(int[] A) {
    if (A == null || A.length <= 1) {
        return 0;
    }

    int count = 0;
    boolean[] used = new boolean[A.length];
    backtrack(A, 0, used, count);
    return count;
}

private static boolean isPerfectSquare(int n) {
    int root = (int) Math.sqrt(n);
    return root * root == n;
}

private static void backtrack(int[] A, int index, boolean[] used, int[] count) {
    if (index == A.length - 1) {
        count[0]++;
        return;
    }

    for (int i = 0; i < A.length; i++) {
        if (used[i]) {
            continue;
        }

        if (index == 0 || isPerfectSquare(A[index - 1] + A[i])) {
            used[i] = true;
            backtrack(A, index + 1, used, count);
            used[i] = false;
        }
    }
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    int n = heights.length;
    int[] left = new int[n];
    int[] right = new int[n];

    // Fill left array
    left[0] = -1;
    for (int i = 1; i < n; i++) {
        int p = i - 1;
        while (p >= 0 && heights[p] >= heights[i]) {
            p = left[p];
        }
        left[i] = p;
    }

    // Fill right array
    right[n - 1] = n;
    for (int i = n - 2; i >= 0; i--) {
        int p = i + 1;
        while (p < n && heights[p] >= heights[i]) {
            p = right[p];
        }
        right[i] = p;
    }

    // Calculate the maximum area
    int maxArea = 0;
    for (int i = 0; i < n; i++) {
        maxArea = Math.max(maxArea, heights[i] * (right[i] - left[i] - 1));
    }

    return maxArea;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }

    Stack<Integer> stack = new Stack<>();
    int maxArea = 0;
    int n = heights.length;

    for (int i = 0; i <= n; i++) {
        int currentHeight = (i == n) ? -1 : heights[i];
        while (!stack.isEmpty() && currentHeight < heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            maxArea = Math.max(maxArea, height * width);
        }
        stack.push(i);
    }

    return maxArea;
}

