    }

    // Find the smallest digit on the right side of (i) which is larger than digits[i]
    int j;
    for (j = digits.length - 1; j > i; j--) {
        if (digits[j] > digits[i]) {
            break;
        }
    }

    // Swap digits at index i and j
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Sort the digits after index i
    Arrays.sort(digits, i + 1, digits.length);

    // Convert the char array back to int
    long result = Long.parseLong(new String(digits));

    // Check if the result is within the int range
