            break;
        }
    }

    // Swap the found digits
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Sort the digits after the (i)th position to get the smallest number
    Arrays.sort(digits, i + 1, len);

    // Convert the array back to a number
    long result = Long.parseLong(new String(digits));

    // Check if the result is within the int range
    return (result > Integer.MAX_VALUE) ? -1 : (int) result;
}

public static int findSmallestInteger(int n) {
        char[] digits = Integer.toString(n).toCharArray();

        // Find the first digit that can be swapped to make the number bigger
        int i;
        for (i = digits.length - 2; i >= 0; i--) {
            if (digits[i] < digits[i + 1]) {
                break;
            }
        }

        if (i == -1) {
            return -1;
        }

        // Find the smallest digit on the right side of (i) which is greater than digits[i]
        int j;
        for (j = digits.length - 1; j > i; j--) {
            if (digits[j] > digits[i]) {
                break;
            }
        }

        // Swap the found digits
        char temp = digits[i];
        digits[i] = digits[j];
        digits[j] = temp;

        // Sort the digits after the (i)的地方
        Arrays.sort(digits, i + 1, digits.length);

        // Convert the char array back to integer
        return Integer.parseInt(new String(digits));
    }

