public static List<String> centerSymmetricNumbers(int n) {
        List<String> result = new ArrayList<>();
        if (n == 0) {
            return result;
        }

        char[] midChars = {'0', '1', '8'};
        int mid = n % 2;
        dfs(0, n - 1, mid, midChars, result, new char[n]);

        return result;
    }

private static void dfs(int start, int end, int mid, char[] midChars, List<String> result, char[] current) {
        if (start > end) {
            if (current[0] != '0') {
                result.add(new String(current));
            }
            return;
        }

        char[] curMidChars = (start == end) ? midChars : new char[]{'0', '1', '6', '8', '9'};

        for (char c : curMidChars) {
            current[start] = c;
            current[end] = getMirror(c);
            dfs(start + 1, end - 1, mid, midChars, result, current);
        }
    }

private static char getMirror(char c) {
        switch (c) {
            case '6':
                return '9';
            case '9':
                return '6';
            default:
                return c;
        }
    }

public static boolean isBoomerang(int[][] points) {
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];
    return (y2 - y1) * (x3 - x1) != (y3 - y1) * (x2 - x1);
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        throw new IllegalArgumentException("Input must be an array of 3 points.");
    }

    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Calculate the area of the triangle formed by the points
    int area = x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2);

    // If the area is zero, the points are collinear and cannot form a boomerang
    return area != 0;
}

